import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BigDecimal num1 = new BigDecimal(reader.readLine().trim());
        BigDecimal num2 = new BigDecimal(reader.readLine().trim());

        BigDecimal resultSum = num1.add(num2);

        String formatted = String.format(Locale.ROOT, "%09.2f", resultSum);
        System.out.println("LABEL=" + formatted);
    }
}
